    $ErrorActionPreference = "Continue"
    & $cloudflared @tunnelArgs 2>&1 | ForEach-Object {
      $line = $_.ToString()
      Write-Host $line

      $match = [regex]::Match($line, "https://[a-zA-Z0-9-]+\.trycloudflare\.com")
      if ($match.Success) {
        Write-Host ""
        Write-Host "============================================================" -ForegroundColor Green
        Write-Host "公网访问地址：" -ForegroundColor Green
        Write-Host $match.Value -ForegroundColor Cyan
