              </p>
            </div>
            <div className="space-y-2">
              <p className="text-sm text-muted-foreground">MaaS Model</p>
              <p className="rounded-lg border bg-muted/40 p-3 text-sm">
                {settings.maasModel}
              </p>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>练习偏好</CardTitle>
