              }}
              labelFormatter={(_, payload) => payload?.[0]?.payload?.date || ""}
              formatter={(value, name) => [
                `${value} 题`,
                name === "count" ? "练习题数" : "正确题数",
              ]}
            />
            <Legend
              formatter={(value) => (value === "count" ? "练习题数" : "正确题数")}
              iconType="circle"
            />
            <Area
              type="monotone"
              dataKey="count"
              stroke="#059669"
              strokeWidth={3}
              fill="url(#countGradient)"
              dot={{ r: 4, strokeWidth: 2, fill: "#ffffff" }}
